var auNoteAll = map[string]string{
	"QBO.ACCOUNTING.AUDIT_LOG_READ":           "Audit log tracks all account activity: user sign-ins, settings changes, edits to customers/suppliers/employees, payroll submissions, and deleted transactions (e.g. deleted invoices). Sign-outs are only recorded when a user explicitly signs out. L2WoVnW6I",
	"QBO.ACCOUNTING.AUDIT_LOG_SEARCH":         "Use the audit log to locate deleted-transaction details for manual re-entry; deleted transactions cannot be restored. L2WoVnW6I",
	"QBO.ACCOUNTING.BUDGET_CREATE":            "Create P&L or balance sheet budgets for the coming year, month, or quarter and compare actuals against them. L7SvmSAsU",
	"QBO.ACCOUNTING.BUDGET_DELETE":            "Delete a budget you no longer need; deleting removes the plan but not posted actuals. L7SvmSAsU",
	"QBO.ACCOUNTING.BUDGET_EDIT":              "Edit existing budget figures directly in QuickBooks Online or via Spreadsheet Sync round-trip. L7SvmSAsU",
	"QBO.ACCOUNTING.BUDGET_READ":              "Read a budget to compare actual income/expenses against plan; budgets by class show per-segment performance. L7SvmSAsU",
	"QBO.ACCOUNTING.CLASS_CREATE":             "Classes represent business segments (departments, product lines); create one class per segment after turning on class tracking. L1QzEOUxM",
	"QBO.ACCOUNTING.CLASS_EDIT":               "Rename or update a class segment; transactions already tagged keep their history. L1QzEOUxM",
	"QBO.ACCOUNTING.CLASS_READ":               "Read a class to review transactions tagged to that segment and run sales/cost/profitability reports by class. L1QzEOUxM",
	"QBO.ACCOUNTING.COA_CREATE":               "Policy-excluded. Not a command. COA create/deactivate stay human-owned.",
	"QBO.ACCOUNTING.COA_DEACTIVATE":           "Policy-excluded. Not a command. COA create/deactivate stay human-owned.",
	"QBO.ACCOUNTING.COA_READ":                 "Chart of accounts is the complete list of company accounts and balances; Account Type + Detail Type determine which reports (Balance Sheet, P&L) display the data. L2yc6KBob",
	"QBO.ACCOUNTING.COA_SEARCH":               "Search the COA by name, number, or type; account numbers are off by default and must be enabled. L2yc6KBob",
	"QBO.ACCOUNTING.DEPOSIT_CREATE":           "Group multiple Undeposited Funds payments into one bank deposit so the record matches the bank statement. L2BBZOPdr",
	"QBO.ACCOUNTING.DEPOSIT_DELETE":           "Deleting a bank deposit removes it everywhere; voiding is not the deposit pattern. Deleted transactions cannot be restored. L5sZV8GYh",
	"QBO.ACCOUNTING.DEPOSIT_EDIT":             "Edit a bank deposit from the account history; customer names in the 'Select payments' section must be changed on the original payment, not on the deposit. L12yKaNhS",
	"QBO.ACCOUNTING.DEPOSIT_READ":             "Read a bank deposit from the account history; missing payments in the Bank Deposit window are usually held outside Undeposited Funds. L2BBZOPdr",
	"QBO.ACCOUNTING.FIXED_ASSET_CREATE":       "Fixed assets are physical assets with a useful life of one year or more (buildings, machinery, vehicles, furniture); products you sell are not fixed assets. L19788yU0",
	"QBO.ACCOUNTING.FIXED_ASSET_DELETE":       "Delete a fixed asset record from the Fixed Assets app (Advanced). Deleting affects the depreciation schedule and posted entries; review with your accountant. L19788yU0",
	"QBO.ACCOUNTING.FIXED_ASSET_EDIT":         "Edit asset details or disposal info in the Fixed Assets app; depreciation entries post at month-end. L19788yU0",
	"QBO.ACCOUNTING.FIXED_ASSET_READ":         "Read a fixed asset and its depreciation schedule from the Fixed Assets app (Advanced). L19788yU0",
	"QBO.ACCOUNTING.FIXED_ASSET_SEARCH":       "Search fixed assets in the Fixed Assets app (Advanced). L19788yU0",
	"QBO.ACCOUNTING.INTEGRATION_TXN_READ":     "no AU help article found",
	"QBO.ACCOUNTING.JOURNAL_CREATE":           "Each journal entry's total debits and total credits must be equal. L6Bzy9mT9",
	"QBO.ACCOUNTING.JOURNAL_DELETE":           "Deleting a journal entry can quickly unbalance accounts; prefer reversing it instead. L2prlrnkh",
	"QBO.ACCOUNTING.JOURNAL_EDIT":             "Edit a journal entry from the account history; adjusting entries can be marked/identified for reporting. L2prlrnkh",
	"QBO.ACCOUNTING.JOURNAL_READ":             "Read a journal entry from the account history or run a Journal report to see all entries. L6Bzy9mT9",
	"QBO.ACCOUNTING.LOCATION_CREATE":          "Locations categorise data by office, region, outlet, or department; available on Plus and Advanced. L2raFkEBC",
	"QBO.ACCOUNTING.LOCATION_READ":            "Read a location to review per-location sales and deposits. L2raFkEBC",
	"QBO.ACCOUNTING.MY_ACCOUNTANT_READ":       "The My Accountant page lists requests/documents from a connected accountant user; accountants work from their own firm page and cannot see other accountants' requests. L323FXOCi",
	"QBO.ACCOUNTING.OPENING_BALANCE_SET":      "Opening balances are entered as a journal entry dated the start-of-tracking day; QuickBooks tracks all opening balances in the Opening Balance Equity account. If you've reconciled the account, consult your accountant before editing the opening balance. L7NcxTbuu",
	"QBO.ACCOUNTING.PREPAID_READ":             "no AU help article found",
	"QBO.ACCOUNTING.PROJECT_CREATE":           "Projects group transactions, estimates, and expenses for a single customer; available on Plus, Advanced, and Intuit Enterprise Suite. L9GAdLMyT",
	"QBO.ACCOUNTING.PROJECT_EDIT":             "Edit a project from its dashboard; changing the assigned customer also updates each invoice and quote in the project but does not auto-notify the new customer. L45yDEgS7",
	"QBO.ACCOUNTING.PROJECT_READ":             "Read a project dashboard for grouped transactions, income, and costs. L9GAdLMyT",
	"QBO.ACCOUNTING.PROJECT_SEARCH":           "Search projects by customer or name; project cost quotes (Advanced) forecast income/costs and track actuals against the plan. L9GAdLMyT",
	"QBO.ACCOUNTING.RECONCILE_CREATE":         "Reconciling matches QuickBooks transactions to the bank/credit card statement for a period; the difference should be AUD0.00. L3XzsllsK",
	"QBO.ACCOUNTING.RECONCILE_READ":           "A reconciliation report is auto-generated after each session; it cannot be exported directly to Excel (manual export required). L1yNaVaOG",
	"QBO.ACCOUNTING.RECURRING_CREATE":         "Create recurring templates for invoices, quotes, expenses, etc.; recurring bill payments and time activities are not supported. L3WoKX2R8",
	"QBO.ACCOUNTING.RECURRING_DELETE":         "Delete a recurring template from the recurring list; duplicate transactions usually mean two templates exist for the same customer. L0XSXgBgS",
	"QBO.ACCOUNTING.RECURRING_EDIT":           "Edit a recurring template's schedule, items, or customer; changes to items/customers/settings may affect future transactions. L0eW5Sjrh",
	"QBO.ACCOUNTING.RECURRING_READ":           "Read a recurring template to review its type, schedule, and linked customer/items. L3WoKX2R8",
	"QBO.ACCOUNTING.RECURRING_SEARCH":         "Search recurring templates by name or customer to find duplicates and failed runs. L0XSXgBgS",
	"QBO.ACCOUNTING.REGISTER_READ":            "The account register (account history) is the booked-state ground truth: it lists an account's complete transaction history and current balance, and is where existing transactions are edited. The register reflects booked transactions; treat it as ground truth, not a staging area. L8V2Hal1f",
	"QBO.ACCOUNTING.REVENUE_RECOGNITION_READ": "Revenue recognition (Advanced) records future-delivered product/service revenue and recognises it over time per a schedule/template. L9vA8v2qt",
	"QBO.ACCOUNTING.TRANSFER_CREATE":          "Record a transfer as a single transaction affecting both accounts; find it in each account's register. L9E8Kvsoy",
	"QBO.ACCOUNTING.TRANSFER_DELETE":          "Delete a transfer from either account's register; deleted transactions cannot be restored. L9E8Kvsoy",
	"QBO.ACCOUNTING.TRANSFER_EDIT":            "Edit a transfer from the account history; the change is reflected in both affected accounts. L9E8Kvsoy",
	"QBO.ACCOUNTING.TRANSFER_READ":            "Read a transfer from either account's register (chart of accounts → account history). L9E8Kvsoy",
	"QBO.ACCOUNTING.TXN_VOID":                 "Voiding sets the amount to zero and marks the transaction Voided, preserving the record; deleting removes it everywhere and cannot be undone. L5sZV8GYh",
	"QBO.ADVANCED.BACKUP_CREATE":              "Online Backup and Restore is a QBO Advanced-only app; turn it on to auto-back up company data and track changes. Not all data can be backed up and not all data can be restored; check the app's can/can't back up and can't restore lists before relying on a backup. L9sTCQn9P",
	"QBO.ADVANCED.BACKUP_RESTORE":             "Restore from the Restore tab by picking a specific date and time, or from the Backups tab to restore a specific backup without changing date/time manually. Do NOT use company data while the Online Backup and Restore app restores it; wait until the status shows a tick before resuming work. L9sTCQn9P",
	"QBO.ADVANCED.CUSTOM_ROLES_CREATE":        "Custom firm roles are created in QuickBooks Online Accountant to grant team members access to firm and client books while protecting sensitive areas. L4Gb8rBPt",
	"QBO.ADVANCED.CUSTOM_ROLES_EDIT":          "Custom roles can be edited and deactivated; a deactivated role can be deleted or restored. L4Gb8rBPt",
	"QBO.ADVANCED.CUSTOM_ROLES_READ":          "Custom firm roles are listed and managed from the Manage users area of QuickBooks Online Accountant; roles show active/deactivated state. L4Gb8rBPt",
	"QBO.ADVANCED.EXPENSE_CLAIMS_CREATE":      "No QBO Advanced-specific expense-claims feature article exists in AU learn-support; employee reimbursements are the closest equivalent and are general QBO (not Advanced-only). Mixing business and personal funds is discouraged; record reimbursements deliberately to keep the General Ledger clean. L02x6NDNe",
	"QBO.ADVANCED.EXPENSE_CLAIMS_READ":        "To check outstanding employee reimbursements, run the Transaction Detail by Account report (Reports > Standard reports). L02x6NDNe",
	"QBO.ADVANCED.EXPENSE_CLAIMS_REVIEW":      "no AU help article found for an Advanced-specific expense-claims review/approval workflow.",
	"QBO.ADVANCED.RECLASSIFY_RUN":             "Reclassify Transactions tool (Accountant Tools) bulk-moves transactions to another account, class, or location; also bulk-reassigns GST codes for historical transactions. Transactions without a customer name cannot be reclassified to Accounts Receivable; transactions without a supplier name cannot be reclassified to Accounts Payable. L249lPKyg",
	"QBO.ADVANCED.REVENUE_RECOGNITION_EDIT":   "QBO Advanced only. Edit an existing schedule by adjusting the service duration period for an item at transaction level, adjusting an entire schedule, or changing an item's price; the schedule auto-adjusts to reflect changes. Altering a schedule after partial recognition (e.g. AUD 200 already recognised on a AUD 1,200 invoice) changes future periods; verify the revised schedule before issuing refunds. L7zVWN22u",
	"QBO.ADVANCED.REVENUE_RECOGNITION_SETUP":  "QBO Advanced only. Turn on revenue recognition in Settings before creating any schedule; if you don't want pre-built templates, create custom revenue recognition templates for invoices. L1BM5CqYO",
	"QBO.ADVANCED.SPREADSHEET_SYNC_IMPORT":    "Advanced/Accountant. Use Create or edit records templates; starred columns required. Validates on import. L0uPf2fZs.",
	"QBO.ADVANCED.TASKS_CREATE":               "In QBO Accountant's Work tab, create projects and add tasks to break down work; assign tasks to specific team members. Workflows that auto-create tasks are available for QuickBooks Online Advanced only. L0IYImRhk",
	"QBO.ADVANCED.TASKS_DELETE":               "Delete a project when it's no longer needed; deleting removes the project and its associated task structure. L0IYImRhk",
	"QBO.ADVANCED.TASKS_EDIT":                 "Edit a project to make changes as needed; task assignments and details update within the Work tab. L0IYImRhk",
	"QBO.ADVANCED.TASKS_READ":                 "All tasks appear in the Tasks menu / Task manager; filter by open, due today, overdue, assigned to you, or all, and by due date, related-to, and assignee. Workflows are available for QuickBooks Online Advanced only. L4vLD7kkw",
	"QBO.ADVANCED.WORKFLOWS_CREATE":           "QBO Advanced only. 60+ workflow automation templates cover invoices, bills, quotes, purchase orders, and bill payments. If a transaction is changed in a third-party app after it's sent for approval, QuickBooks will NOT start a new approval. L6uaB8H5G",
	"QBO.ADVANCED.WORKFLOWS_EDIT":             "Manage workflows by editing, copying, turning off, or deleting them at any time. L6uaB8H5G",
	"QBO.ADVANCED.WORKFLOWS_READ":             "Workflows are listed and managed from the Workflows area in QBO Advanced; each shows its trigger conditions and active/off state. Workflows are available for QuickBooks Online Advanced only. L6uaB8H5G",
	"QBO.COMPANY.ACCOUNTANT_INVITE":           "Invite an accountant from Manage users; the invitee receives an email and their status moves from Invited to Active on acceptance. You need primary admin or company admin access to invite an accountant. L2AcdYvHw",
	"QBO.COMPANY.ATTACHMENT_READ":             "Attachments can be added to customer and supplier profiles and to transactions; the Attachments list lets you view, download, edit, and remove files. You cannot add PDF attachments to statements sent to customers. L8XvMBCgd",
	"QBO.COMPANY.BILLS_IMPORT":                "File import of bills (company lists). Pair with expenses bill import. First row maps. No bulk undo.",
	"QBO.COMPANY.BOOKS_CLOSE":                 "Closing sets a lock date; transactions on or before that date cannot be changed or deleted without approval. Closing the books is a lock, not a delete; keep the closing-date password safe. L59LelyPM",
	"QBO.COMPANY.BUSINESS_FEED_READ":          "The transactions hub is the starting point for getting transactions into QuickBooks Online: either a live bank connection (bank feed) or manual CSV upload. No AU help article describes a dedicated 'business feed' surface; the closest concept is the bank-feed/transactions hub. L89kOgMFk",
	"QBO.COMPANY.COA_IMPORT":                  "Import a chart of accounts via Settings > Import data; CSV, Google Sheets, or XLS/XLSX accepted; first row is used for mapping (not imported). You cannot migrate data into a QuickBooks Online company that already contains data; use a new empty account. L4OYJRFdj",
	"QBO.COMPANY.CONTACT_FORM_CREATE":         "Lead-capture contact forms. AU help L4STWrFAS.",
	"QBO.COMPANY.CURRENCY_CREATE":             "Add a currency from the Currencies page after multicurrency is enabled; assign one currency per customer/supplier/bank or credit card account. Once multicurrency is enabled it cannot be turned off and the home currency cannot be changed. L5krkKQi8",
	"QBO.COMPANY.CURRENCY_DELETE":             "A currency can be deleted only when no transactions are attached to it. Multicurrency itself cannot be turned off once enabled. L5krkKQi8",
	"QBO.COMPANY.CURRENCY_EDIT":               "You can override the downloaded rate with your own exchange rate per transaction or for multiple transactions. Once an account has a transaction posted, its currency cannot be changed. L5krkKQi8",
	"QBO.COMPANY.CURRENCY_READ":               "Currencies page lists home currency plus added foreign currencies; the Currency column on the Chart of Accounts shows each account's assigned currency. Multicurrency is only available on QuickBooks Online Essentials, Plus, and Advanced (not Simple Start). L5krkKQi8",
	"QBO.COMPANY.CURRENCY_REVALUE":            "Home currency adjustments recompute the home-currency value of foreign A/R, A/P, and bank balances at a new rate, posting a journal entry. Home currency adjustments with non-zero dollar amounts should be reviewed; they are journal entries and cannot be trivially undone. L40cB0sr4",
	"QBO.COMPANY.CUSTOMERS_IMPORT":            "Import customers from Outlook, Gmail, Excel, or Google Sheets (CSV/XLS/XLSX); first row maps fields and is not imported. You cannot import a contact that already exists; rename duplicates before importing. L4OYJRFdj",
	"QBO.COMPANY.CUSTOM_FIELD_CREATE":         "Create custom fields (text, number, dropdown) for invoices, sales receipts, refund receipts, quotes, adjustment notes, purchase orders, expenses, bills, cheques, supplier credits, and credit card credits. Enhanced custom fields require QuickBooks Online Advanced; basic custom fields on sales forms are available on Essentials/Plus/Advanced. L56PQNif3",
	"QBO.COMPANY.CUSTOM_FIELD_DELETE":         "Remove a custom field from a form or delete it; removing a field from a reviewed transaction does not delete the transaction. Deleting a custom field removes it from all forms that used it. L56PQNif3",
	"QBO.COMPANY.CUSTOM_FIELD_EDIT":           "Edit custom field name, data type, and values; fields can be added and removed from transactions (e.g. to flag a transaction for review). Custom fields on purchase orders require Plus or Advanced. L56PQNif3",
	"QBO.COMPANY.CUSTOM_FIELD_READ":           "Custom fields appear on sales forms, purchase orders, expense forms, and customer/supplier profiles; each field supports up to 100 values. Enhanced custom fields (filter/sort, supplier/expense fields) require QuickBooks Online Advanced; custom fields on purchase orders require Plus or Advanced. L56PQNif3",
	"QBO.COMPANY.FORM_STYLE_EDIT":             "Edit logo, company info, fields (e.g. Service Date column), appearance, and email messages on sales forms. The modernised template cannot be edited; use the standard template for default customisation. L57kKA6b6",
	"QBO.COMPANY.FORM_STYLE_READ":             "Sales form styles (invoices, quotes, sales receipts) are customised under the Customise forms / Design area: company info, logo, fields, appearance, and layout. Only the standard template can be set as default; the modernised template cannot be edited. L57kKA6b6",
	"QBO.COMPANY.ITEMS_IMPORT":                "Import products and services from Excel or CSV via Batch-import products & services; a sample file defines the importable fields. Overwrite cannot be undone after you select Import. L4OYJRFdj",
	"QBO.COMPANY.LIST_READ":                   "Lists include chart of accounts, products and services, customers, suppliers, classes, locations, and custom fields; export all lists/reports as a single Excel zip from the export tool. Only active (or invited) users/accounts/classes/locations/custom fields count toward each usage limit. L1xleDrLp",
	"QBO.COMPANY.MARKETING_READ":              "Marketing integrations live under Customers & leads > Marketing; the Mailchimp integration syncs QuickBooks data to segment Mailchimp audiences. Mailchimp is a third-party service; QuickBooks support cannot assist with the Mailchimp account itself. L1UOG3NYz",
	"QBO.COMPANY.ROLE_CREATE":                 "Custom roles (define access per area: banking, sales, payroll, etc.) require QuickBooks Online Advanced. Custom roles are a QBO Advanced feature; not available on Simple Start/Essentials/Plus. L66POfRrI",
	"QBO.COMPANY.ROLE_DELETE":                 "Custom firm roles can be deactivated (restorable) or deleted (permanent) in QuickBooks Online Accountant. Deleting a role removes it from all assigned team members. L4Gb8rBPt",
	"QBO.COMPANY.ROLE_EDIT":                   "Edit custom firm roles in QuickBooks Online Accountant; assign team members to a role after creation. Deactivating a role can be restored; deleting a role is permanent. L4Gb8rBPt",
	"QBO.COMPANY.ROLE_READ":                   "Billable roles: primary admin, company admin, standard all access, customer/marcom, supplier/marcom, inventory, payroll. L66POfRrI",
	"QBO.COMPANY.SEARCH":                      "No AU help article found for a company-level global search primitive.",
	"QBO.COMPANY.SETTINGS_EDIT":               "Editable: company name/address/contact/ABN (Company), sales forms/payment terms/progress invoicing/automated reminders (Sales), billable expenses/purchase orders (Expenses), accounting method, categories, financial year, multicurrency (Advanced). Only the primary admin can edit business details in the Company tab. L6cZwzGez",
	"QBO.COMPANY.SETTINGS_READ":               "Settings live under Gear > Account and settings with tabs: Company, Sales, Expenses, Time, Advanced. L6cZwzGez",
	"QBO.COMPANY.SUPPLIERS_IMPORT":            "Import suppliers from Outlook, Gmail, Excel, or Google Sheets (CSV/XLS/XLSX); same field-mapping and first-row rules as customers. Duplicate supplier names are rejected; rename duplicates first. L4OYJRFdj",
	"QBO.COMPANY.TAG_CREATE":                  "Tags are being migrated to custom fields; from 16 May 2025 there is no option to create new tags for reporting. New tag creation is disabled as of 16 May 2025; customers who never used tags lose the option by 19 May 2025. L7x3G0aLv",
	"QBO.COMPANY.TAG_DELETE":                  "Delete a tag value from its custom-field dropdown; tags not migrated are removed when the tag feature is retired. Existing tag usage is supported only until 19 May 2028. L7x3G0aLv",
	"QBO.COMPANY.TAG_EDIT":                    "Edit tag values via the custom-field dropdown that the tags were migrated to. Tag editing is deprecated; migrate to custom fields before 19 May 2028. L7x3G0aLv",
	"QBO.COMPANY.TAG_READ":                    "Tags are flexible tracking labels that do not affect the General Ledger unless you run a Profit and Loss by Tag Group report. Tags are being retired: from 16 May 2025 new tags can no longer be created; existing tag users can continue until 19 May 2028. Migrate tags to custom fields for ongoing tracking. L7x3G0aLv",
	"QBO.COMPANY.USER_CREATE":                 "Invite by email; the new user receives an invite link and creates or signs in to an Intuit Account to accept. Only users with the correct permissions can manage user profiles. L1welhiJZ",
	"QBO.COMPANY.USER_DELETE":                 "Deleting a user is permanent; the user's history is still visible in the audit log. If the user is an Admin, remove their payroll access before deleting. L1welhiJZ",
	"QBO.COMPANY.USER_EDIT":                   "Edit a user's role/permissions from Manage users; subscription tier determines which billable roles are available. Deleting a user is permanent, but their history remains in the audit log; remove payroll access separately for admin users. L1welhiJZ",
	"QBO.COMPANY.USER_READ":                   "User list is on the Manage users page; each email address on the plan is assigned one role (primary admin, company admin, standard all access, etc.). The QuickBooks mobile app supports only admin and standard all access roles; other roles must use the web app. L1welhiJZ",
	"QBO.CUSTOMERS.APPOINTMENT_READ":          "Scheduled meetings are listed in the Upcoming section of the Appointments page, where you can join the video meeting. L7pZhPDEP",
	"QBO.CUSTOMERS.APPOINTMENT_SEARCH":        "The Appointments page lists upcoming video meetings with existing customers and new leads. L7pZhPDEP",
	"QBO.CUSTOMERS.CONTRACT_READ":             "Contract builder sends a contract for e-signature directly within QuickBooks Online; the customer receives an email with a link to review and sign. L0LenCa69",
	"QBO.CUSTOMERS.CONTRACT_SEARCH":           "Manage all contracts in one location and review their e-signature status. L0LenCa69",
	"QBO.CUSTOMERS.CUSTOMER_CREATE":           "Add customer profiles to the customer list so they can be included in future transactions, reports and invoices. Once you record transactions with a customer, you cannot change the currency in their profile; create a new customer with the desired currency instead. L0M9mMZmd",
	"QBO.CUSTOMERS.CUSTOMER_CREDIT_TRANSFER":  "Move credit between customers (usually a journal). L4vT5bz8K.",
	"QBO.CUSTOMERS.CUSTOMER_DELETE":           "Deleting a customer is the same as making the profile inactive: it hides the customer from lists and menus while keeping their data available in reports. You cannot delete a customer who has unbilled charges; resolve the charges first (create an invoice, delete the charge/credit, or mark the expense non-billable), or merge the customer instead. L5wGjGbhV",
	"QBO.CUSTOMERS.CUSTOMER_EDIT":             "A phone number saved in the customer details pane will not automatically show on sales transactions (quotes, invoices, sales receipts); create a custom field to display it (up to three custom fields per form type). Changing customer info updates previously sent invoices or recurring transactions that use this info, such as billing, shipping and email addresses, or payment methods and terms. L2Ph3B88N",
	"QBO.CUSTOMERS.CUSTOMER_MERGE":            "Keep one profile; duplicate goes inactive and history moves. Recreate manually to undo. L5AOyW9kw / L6s6B3PQd.",
	"QBO.CUSTOMERS.CUSTOMER_READ":             "The Transaction List by Customer report shows all transactions for a customer and can be modified to show only charges. L0iFLYKPV",
	"QBO.CUSTOMERS.CUSTOMER_SEARCH":           "The display name identifies the customer profile; before merging duplicates, edit the display name of the profile to remove (e.g. add 'duplicate') to avoid confusion. L6s6B3PQd",
	"QBO.CUSTOMERS.OPPORTUNITY_CREATE":        "Manually add leads in the Customer Hub to track leads and their status in the sales cycle all in one place. L3GZDOdYV",
	"QBO.CUSTOMERS.OPPORTUNITY_READ":          "Leads are listed and prioritised on the Leads page in QuickBooks as Hot or Warm. L5wH7M8qS",
	"QBO.CUSTOMERS.OPPORTUNITY_SEARCH":        "The Leads page lists and prioritises leads as Hot or Warm; items marked 'Not a lead' can be archived. L6KtREjm9",
	"QBO.CUSTOMERS.OVERVIEW_READ":             "The Customer AI automates lead sourcing and prioritisation from your Gmail or Outlook inbox; after connecting it reads 30 days of emails to identify potential leads for review. L6KtREjm9",
	"QBO.CUSTOMERS.PROPOSAL_CREATE":           "Use the proposal builder to create a proposal with your branding, add content elements, and email it to the customer for e-signature. L6nlEXigC",
	"QBO.CUSTOMERS.PROPOSAL_READ":             "Track a proposal's status on the Proposals page after sending it to the customer. L6nlEXigC",
	"QBO.CUSTOMERS.PROPOSAL_SEARCH":           "The Proposals page lists proposals together with their current status (sent, approved, or declined). L6nlEXigC",
	"QBO.CUSTOMERS.REVIEW_READ":               "QuickBooks Online offers an optional post-invoice survey that collects a 5-star rating, feedback, whether the customer would work with you again, and referrals. Customer feedback surveys must be turned on in Account and settings before survey responses are collected. L1QjCRCpN",
	"QBO.CUSTOMERS.REVIEW_SEARCH":             "The Work Requests widget shows the customers that have said they'd like to work with you again, with the recorded time frame. L1QjCRCpN",
	"QBO.EXPENSES.BANK_FEE_CREATE":            "Record bank fees as an expense against the bank account. L83BBLKBK.",
	"QBO.EXPENSES.BILL_CREATE":                "A bill records what you owe (Accounts Payable) for a purchase you will pay later; use Expense/Cheque instead when you pay immediately. Do not enter a bill for a purchase you already paid — use Expense or Cheque, otherwise you double-count the payable. L1e9Ce5J7",
	"QBO.EXPENSES.BILL_DELETE":                "Deleting a bill removes it from reports; a record remains in the Audit log. If the bill was paid, delete the bill payment first or you create an unapplied cash bill payment expense on the P&L. L1RNWhKVT",
	"QBO.EXPENSES.BILL_EDIT":                  "Bills can be reviewed and edited from the Bills page sections: For review, Unpaid, Paid. Edits to a bill that was already paid can create an Unapplied Cash Bill Payment Expense on cash-basis P&L — review after editing. L1e9Ce5J7",
	"QBO.EXPENSES.BILL_FORM_DELETE":           "Deletes a bill form/line entry; for batch deletion of multiple bill forms use the batch transactions tool (QuickBooks Online Advanced). Batch delete is irreversible from the UI; verify via Audit log. L1RNWhKVT",
	"QBO.EXPENSES.BILL_IMPORT":                "CSV bill import on Essentials/Plus/Advanced. Map supplier, dates, GST. L4Q6QWsRw.",
	"QBO.EXPENSES.BILL_LIST_CREATE":           "Batch transactions tool creates several different bills at once, or duplicates one bill across multiple suppliers in a single save. Advanced-only feature; not available on Essentials/Plus/Simple Start. L9zalLLbI",
	"QBO.EXPENSES.BILL_LIST_EDIT":             "Batch edit applies the same change to multiple bill forms at once (Advanced only). Advanced-only; bulk edits are not reversible in one action — review the Audit log. L9zalLLbI",
	"QBO.EXPENSES.BILL_PAY":                   "Pay bills clears one or many open bills for a supplier and generates the payment (cheque/card/cash); credits are applied to reduce the total. Paying a bill without applying it to the bill id creates an Unapplied Cash Bill Payment Expense on cash-basis P&L. L3eEpgbLD",
	"QBO.EXPENSES.BILL_READ":                  "Read a single bill by id; the Bills page groups bills into For review, Unpaid, and Paid. L8VbbnAd2",
	"QBO.EXPENSES.BILL_SEARCH":                "Search/list bills from the Expenses page or Bills page; filter by supplier and payment status. L8VbbnAd2",
	"QBO.EXPENSES.CHEQUE_BOUNCE":              "Returned cheque: reverse via cheque or expense plus any bank fee. L4rxNrG0Y L4O144llZ.",
	"QBO.EXPENSES.CHEQUE_CREATE":              "AU spelling is 'cheque' (not 'check'); CLI verbs and fields use cheque. The QBO API/UI label is also 'Cheque'. Printed cheques must be formatted for QuickBooks; own cheque stock needs the QuickBooks layout. L2JKk4Xgn",
	"QBO.EXPENSES.CHEQUE_DELETE":              "AU spelling is 'cheque' (not 'check'); CLI verbs and fields use cheque. The QBO API/UI label is also 'Cheque'. Prefer void over delete to preserve cheque numbering and the audit trail. L2kHjsvzf",
	"QBO.EXPENSES.CHEQUE_EDIT":                "AU spelling is 'cheque' (not 'check'); CLI verbs and fields use cheque. The QBO API/UI label is also 'Cheque'. Editing a cleared/reconciled cheque breaks reconciliation — undo the reconciliation first. L2JKk4Xgn",
	"QBO.EXPENSES.CHEQUE_READ":                "AU spelling is 'cheque' (not 'check'); CLI verbs and fields use cheque. The QBO API/UI label is also 'Cheque'. L2JKk4Xgn",
	"QBO.EXPENSES.CHEQUE_REPRINT":             "Reprint an existing cheque/sales form. Does not post a new payment. L6HMWrs2f.",
	"QBO.EXPENSES.EXPENSE_CREATE":             "An expense records a purchase you have already paid (cash/credit card); use a Bill when you will pay later. Avoid mixing business and personal funds; if it happens, record the transaction then reimburse — do not leave it unrecorded. L1XojuBAW",
	"QBO.EXPENSES.EXPENSE_DELETE":             "Deleting an expense removes it from reports; a record remains in the Audit log. If the expense was billable to a customer, deleting it affects the invoice that charges the customer. L367B8Y2F",
	"QBO.EXPENSES.EXPENSE_EDIT":               "Expenses can be edited any time; edits to a billable expense impact the customer invoice. Editing an expense matched to a bank transaction can break the match — re-review in For Review. L1XojuBAW",
	"QBO.EXPENSES.EXPENSE_FORM_DELETE":        "Deletes an expense form/line entry; for multiple forms use the batch tool (Advanced). Deletion is irreversible from the UI; verify via Audit log. L367B8Y2F",
	"QBO.EXPENSES.EXPENSE_LIST_CREATE":        "Batch transactions tool creates several expenses at once, or duplicates one expense across multiple payees in a single save (Advanced). Advanced-only feature. L9zalLLbI",
	"QBO.EXPENSES.EXPENSE_LIST_EDIT":          "Batch edit applies one change to multiple expense forms at once (Advanced). Advanced-only; bulk edits are not reversible in one action. L9zalLLbI",
	"QBO.EXPENSES.EXPENSE_READ":               "Read a single expense by id; fields include payee, payment account, line items, GST per line, billable flag, and project. L1XojuBAW",
	"QBO.EXPENSES.EXPENSE_RECATEGORISE":       "Recategorise changes the category account (and optionally the From/To payee) of an existing expense or a pending bank transaction. QuickBooks may warn before categorising if the transaction usually matches a record not yet synced (bill pay, payroll, expense app) — pausing avoids duplicate entries. L6qyw0PvP",
	"QBO.EXPENSES.EXPENSE_SEARCH":             "Search/list expenses from the Expenses page; filter by payee, account, date, and project. L1XojuBAW",
	"QBO.EXPENSES.EXPENSE_SPLIT":              "A split breaks one transaction across multiple category accounts; in the account register a single transaction otherwise maps to one account. Split amounts must total the original transaction or the register goes out of balance. L2uiuS0Ls",
	"QBO.EXPENSES.GIFT_CERTIFICATE_CREATE":    "Vouchers bought from a supplier sit as an asset/prepaid until redeemed. L9Me3DImI.",
	"QBO.EXPENSES.MILEAGE_CREATE":             "AU businesses can claim a deduction for up to 5,000 km per vehicle each financial year (cents-per-km method); up to 3 vehicles including motorbikes. Past 5,000 km per vehicle, QuickBooks shows $0 — tracking continues but no additional deduction. L2qPCRGgI",
	"QBO.EXPENSES.MILEAGE_DELETE":             "Delete a trip from the Trips list; on Android use the trash icon, on browser Delete, on iPhone Delete Trip. Deleting a trip removes it from mileage reports/exports — keep a logbook backup for ATO substantiation. L2qPCRGgI",
	"QBO.EXPENSES.MILEAGE_EDIT":               "Edit a trip's vehicle, distance, and business/personal classification from the Trips review screen. L2qPCRGgI",
	"QBO.EXPENSES.MILEAGE_READ":               "Read a single trip by id; fields include vehicle, date, distance (km), trip type, and allowable amount. L2qPCRGgI",
	"QBO.EXPENSES.MILEAGE_SEARCH":             "Search/list trips; export mileage to CSV (tax-year or all-time) for tax programs/accountants. L2qPCRGgI",
	"QBO.EXPENSES.OVERVIEW_READ":              "Overview of the expenses domain: bills (pay later, A/P), cheques (pay now from bank), expenses (pay now from bank/CC), supplier credits, pay-bills, receipts, and mileage. Choose the right transaction type up front: Bill (deferred) vs Cheque/Expense (immediate) — wrong choice double-counts payables or payments. L0ZtL2TYI",
	"QBO.EXPENSES.RECEIPT_DELETE":             "Deletes a receipt/bill capture from the Receipts tab; reviewed (already-added) receipts can be swiped back to For Review to undo. Deleting a receipt that was already added to books does not delete the created expense/bill — delete that transaction separately. L862MmZHn",
	"QBO.EXPENSES.RECEIPT_EXPENSE_CREATE":     "When no existing transaction matches, create a new expense (or bill) from the receipt; when one or more matches exist, match instead of creating to avoid duplicates. Creating an expense when a matching bank transaction already exists produces a duplicate — prefer Match. L862MmZHn",
	"QBO.EXPENSES.RECEIPT_READ":               "Read a single receipt/bill capture; fields include extracted date, amount, supplier, and last four digits of the credit card. L862MmZHn",
	"QBO.EXPENSES.RECEIPT_SEARCH":             "Search/list receipt captures in the Receipts tab; filter by match status and supplier. L862MmZHn",
	"QBO.EXPENSES.RECEIPT_UPLOAD":             "Upload receipts/bills from computer, Google Drive, mobile snap, or email to a custom QuickBooks address. Email forwarding must come from the authorised address; unauthorised senders are rejected. L862MmZHn",
	"QBO.EXPENSES.SUPPLIER_CREATE":            "Adding a supplier lets you record bills/expenses and track what you owe in real time. Currency is immutable once the supplier has transactions — plan multicurrency before recording purchases. L29cgm4Ag",
	"QBO.EXPENSES.SUPPLIER_DELETE":            "Suppliers cannot be deleted — they can only be made permanently inactive. Merging is irreversible: the merged (duplicate) profile must be manually recreated to restore it. L3LHjYszk",
	"QBO.EXPENSES.SUPPLIER_EDIT":              "Edit supplier profile fields (name, address, custom fields, TPAR flag) from the Suppliers tab. Editing a supplier used in unreconciled transactions can affect matching — review bank matches after bulk supplier edits. L0dql1u1h",
	"QBO.EXPENSES.SUPPLIER_MERGE":             "Transactions move to the kept supplier; duplicate becomes inactive. Choose keep carefully. L0NPj861i.",
	"QBO.EXPENSES.SUPPLIER_READ":              "Read a single supplier by id; the Suppliers tab shows profile, transactions, and the Suppliers money bar (overdues, current, totals). L338TnVyK",
	"QBO.EXPENSES.SUPPLIER_SEARCH":            "Search/list suppliers from the Suppliers tab; view all transactions for a specific supplier. L338TnVyK",
	"QBO.EXPENSES.VENDOR_CREDIT_CREATE":       "A supplier credit (vendor credit) records money returned/owed by a supplier; method depends on how the original purchase was recorded (expense/cheque vs bill). Applying a supplier credit to the wrong original transaction type misstates A/P and bank balances — match the credit method to the original purchase method. L2y1KARni",
	"QBO.EXPENSES.VENDOR_CREDIT_DELETE":       "Deleting a supplier credit removes it from reports; a record remains in the Audit log. Deleting an applied credit can create an Unapplied Cash Bill Payment Expense — review the P&L after deletion. L2y1KARni",
	"QBO.EXPENSES.VENDOR_CREDIT_EDIT":         "Edit a supplier credit's amount or line items; the method must still match how the original purchase was recorded. Editing an applied credit changes the linked bill payment — re-verify the payment and reconciliation. L2y1KARni",
	"QBO.EXPENSES.VENDOR_CREDIT_READ":         "Read a single supplier credit by id; fields include supplier, date, amount, line items, and applied bills. L2y1KARni",
	"QBO.FEED.ACCOUNT_LINK":                   "Three AU feed types: Open Banking (CDR, 365-day consent, real-time), standard (web-scrape), and direct (SISS-processed, ~10 business days to activate). AU: legacy feeds are being disconnected on bank-specific cutoff dates; migrate to Open Banking before the deadline or imports stop. L4yDAHMNH",
	"QBO.FEED.ACCOUNT_LIST":                   "Lists connected bank/credit card accounts and their feed connection type: Open Banking, standard, or direct. AU: banks are phasing out legacy feeds for Open Banking; check the connection status page for disconnection dates. L4yDAHMNH",
	"QBO.FEED.REC_AUTO_ADJUST":                "When a reconciliation will not balance, QuickBooks can create an adjusting entry; its memo reads 'Reconcile Adjustment'. Adjusting to force a balance masks the real discrepancy; accountant review recommended before accepting. L3mZimyAb",
	"QBO.FEED.REC_REPORT":                     "QuickBooks auto-generates a reconciliation report per session; view via Reconcile > History by account. L1yNaVaOG",
	"QBO.FEED.RULE_CREATE":                    "Bank rules auto-categorise Pending rows and show a RULE badge; QuickBooks learns and improves over time. A rule based on bank text will not fire on description and vice versa; verify the basis. L0mjJl0nD",
	"QBO.FEED.RULE_DELETE":                    "Deleting a rule stops auto-categorisation for future matching Pending rows. Deletion is irreversible; consider exporting rules first (see rules import/export). L0mjJl0nD",
	"QBO.FEED.RULE_EDIT":                      "Editing a rule changes how future Pending rows are categorised; already-posted rows are not retroactively changed. L0mjJl0nD",
	"QBO.FEED.RULE_READ":                      "Lists bank rules and their conditions/category/auto-add settings. L0mjJl0nD",
	"QBO.FEED.RULE_SEARCH":                    "Filter rules to diagnose why a rule is/is not applying (bank text vs description basis). L0mjJl0nD",
	"QBO.FEED.TXN_ATTACH":                     "Attach notes or files to a transaction for context; 'Requests for more information' lets you gather details from clients/team from a bank transaction. L2b0wMYtL",
	"QBO.FEED.TXN_BATCH_ACCEPT":               "Accounting AI 'Ready to post' groups highest-confidence rows for one-click acceptance; review before posting. Batch-accepting AI-grouped rows bypasses per-row review; verify confidence badges first. L0hR7A9Zf",
	"QBO.FEED.TXN_CATEGORISE":                 "Categorising assigns an income/expense (or other) account; the choice drives tax forms and reports. If QuickBooks shows a potential-match warning, pause: categorising may create a duplicate when the matching record has not arrived yet. L3u8U0wRA",
	"QBO.FEED.TXN_EXCLUDE":                    "Excluding a downloaded transaction moves it to the Excluded list; QuickBooks then ignores it for tax and reports but keeps a record. Excluding is not the same as deleting: excluded rows remain and can be restored (undo-excluded). L2T2AKDUs",
	"QBO.FEED.TXN_EXCLUDED":                   "Lists downloaded transactions the user has excluded; QuickBooks ignores them for tax and reports. L2T2AKDUs",
	"QBO.FEED.TXN_IMPORT":                     "Date column required; AU locale expects dd/MM/yyyy. Incorrect column mapping silently fails to read data; verify mapping stage. L4BjLWckq",
	"QBO.FEED.TXN_LOOKUP":                     "Searches transaction fields (amount, description, name, date, etc.); results may span all transaction types. L4hBemuUP",
	"QBO.FEED.TXN_MATCH":                      "Match pairs a downloaded row with an existing QuickBooks record of the same amount within 90 days before and 20 days after. Matching to the wrong record creates bookkeeping errors; unmatch returns the downloaded row to For Review. L6qyw0PvP",
	"QBO.FEED.TXN_PENDING":                    "Lists downloaded transactions awaiting review (the For Review / Pending tab). L86TTVI3Y",
	"QBO.FEED.TXN_POPULATION":                 "Reports how many transactions are available/queued for a connected feed (pending vs already imported). Direct feeds do not backfill history before the bank approval date; upload those manually. L86TTVI3Y",
	"QBO.FEED.TXN_POSTED":                     "Lists feed transactions already posted to the books (Categorised/Matched/Added). Editing a posted row that has been reconciled can unbalance a reconciliation; review the reconciliation report first. L7Xbj9hve",
	"QBO.FEED.TXN_SPLIT":                      "Use a split when one downloaded row must hit multiple accounts. L2uiuS0Ls",
	"QBO.FEED.TXN_TAG":                        "Tags are tracking labels that do not affect the General Ledger unless you run a Profit and Loss by Tag Group report. Do not rely on tags for new reporting setups; plan migration to custom fields. L7x3G0aLv",
	"QBO.FEED.TXN_TRANSFER":                   "Posts a downloaded row as a transfer between bank and credit card accounts. Multi-currency transfers between bank and credit card accounts are not supported. L8ctRmlZz",
	"QBO.FEED.TXN_UNDO_EXCLUDED":              "Restoring an excluded transaction returns it to the For Review / Pending list so it can be categorised and posted. Only previously excluded rows can be undone here; manually added (deleted) transactions cannot be restored this way. L2T2AKDUs",
	"QBO.FEED.TXN_UNPOST":                     "Unmatching/undoing a posted match disconnects the pair and returns the downloaded row to For Review. Undoing a posted row that is already reconciled can unbalance the reconciliation; review the reconciliation report first. L7Xbj9hve",
	"QBO.INVENTORY.ADJUST_CREATE":             "A quantity adjustment changes QOH without recording a purchase or sale; use it to match actual stock after a stock take. Editing or deleting saved adjustment entries can greatly impact accounting; consult an accountant if unsure. L6O3QhOEZ",
	"QBO.INVENTORY.CONSIGNMENT_CREATE":        "Track consignment with classes + a custom report, not a separate stock type. L8z1aYyeA.",
	"QBO.INVENTORY.ITEM_CREATE":               "Turn on inventory tracking before creating Inventory-type items so QOH is managed automatically. Costing method cannot be changed after inventory items exist — choose FIFO or MAC before creating the first item. L6eIyKNFi",
	"QBO.INVENTORY.ITEM_DELETE":               "QBO makes items inactive rather than deleting them; inactive items are hidden from sales forms, lists, and reports but can be reactivated. To remove an Inventory item: adjust qty to zero, post the balancing journal entry, then make it inactive — do not inactivate while QOH > 0. L3iSvRjH4",
	"QBO.INVENTORY.ITEM_EDIT":                 "Edit initial cost by editing the starting value rather than recreating the item. Changing an Inventory item's type is not supported while it holds stock — adjusting inventory to change type deletes Balance Sheet assets; consult an accountant. L9yEFWaNM",
	"QBO.INVENTORY.ITEM_READ":                 "Item record exposes QOH, Qty on PO (on order, not yet received), reorder point, initial cost, and income/asset accounts. L1EnvzoyB",
	"QBO.INVENTORY.ITEM_RECEIPT_CREATE":       "Use an Item Receipt (instead of a Bill) when goods arrive before the supplier bill — it increases Inventory Asset and Accounts Payable without posting COS. Enabling Item Receipts is one-way — Bills will no longer update QOH after it is on. L5xIhKRpV",
	"QBO.INVENTORY.ITEM_RECEIPT_EDIT":         "Editing received quantities updates Inventory Asset and A/P; the linked PO's received-qty display updates accordingly. Once the linked Bill is created the PO closes and this cannot be undone — verify receipt quantities before billing. L5xIhKRpV",
	"QBO.INVENTORY.ITEM_RECEIPT_READ":         "A receipt shows received quantities, the linked PO, the supplier, and whether a Bill has been attached. L5xIhKRpV",
	"QBO.INVENTORY.ITEM_RECEIPT_SEARCH":       "Item receipts are accessed via the Expenses & Bills transaction list; no dedicated inventory-receipt report is documented in AU help. L5xIhKRpV",
	"QBO.INVENTORY.ITEM_SEARCH":               "The Products & Services list is the item catalogue; add the Quantity on PO column to see on-order counts alongside QOH. L7ocoLmqP",
	"QBO.INVENTORY.OVERVIEW_READ":             "Inventory Asset (Balance Sheet) holds stock value at FIFO or Moving Average Cost; COGS (P&L) increases by the item cost when sold, gross profit = sale income − COGS. QOH, COGS, and Inventory Asset values may be misstated on a cash basis when inventory is received and paid across periods — use accrual basis for inventory reports. L9BfAQWK5",
	"QBO.INVENTORY.OVERVIEW_SEARCH":           "Inventory features are Plus/Advanced only; Simple Start/Essentials cannot track quantities. L7ocoLmqP",
	"QBO.INVENTORY.PURCHASE_ORDER_CREATE":     "Purchase Orders require Plus or Advanced and the PO feature turned on. Only items marked as purchased from suppliers are copied when converting a quote to a PO — verify item setup first. L2mVpjOoq",
	"QBO.INVENTORY.PURCHASE_ORDER_DELETE":     "Deleting an unsaved bill/expense removes the PO link from the Action column dropdown. Unlinking a saved bill does not revert PO status to Open — set it back manually. L9pRK49uC",
	"QBO.INVENTORY.PURCHASE_ORDER_EDIT":       "Edit the PO quantity directly when the wrong quantity was sent; do not edit inventory to compensate. Converting open POs to bills is how QBO counts goods as on the way — edit POs before conversion to keep inventory counts accurate. L4VGho4MW",
	"QBO.INVENTORY.PURCHASE_ORDER_PARTIAL":    "Add only the received part of a PO to a bill/expense/cheque to record a partial receipt; the remaining lines stay open on the PO. After unlinking a saved bill the PO remains Closed — manually set it back to Open to continue receiving. L9pRK49uC",
	"QBO.INVENTORY.PURCHASE_ORDER_READ":       "A PO shows line items, quantities, supplier, status (Open/Closed), and received quantities. L1EnvzoyB",
	"QBO.INVENTORY.PURCHASE_ORDER_SEARCH":     "Open POs are listed from the Expenses & Bills transaction list; sent POs can be re-sent from the Action column. L9o7cz3sj",
	"QBO.PAYROLL.BPAY_CREATE":                 "AU pays via BPAY/ABA files, not US direct deposit. L7LkysE03.",
	"QBO.PAYROLL.DEDUCTION_CREATE":            "Create deduction categories first, then attach to the employee. CSA uses Payment Reference. L3nmCl2jx.",
	"QBO.PAYROLL.DEDUCTION_EDIT":              "Edit an employee deduction; next pay run picks up the change. L3nmCl2jx.",
	"QBO.PAYROLL.DEDUCTION_READ":              "List deductions on the employee or pay-run inclusion.",
	"QBO.PAYROLL.EMPLOYEE_READ":               "Employee records hold TFN, bank account, super fund choice and employment details; an employee cannot be terminated until all associated pay runs are finalised. Employee vs contractor classification is an ATO determination, not a QuickBooks setting; misclassification affects PAYG withholding and super obligations. L57cr8Qlb",
	"QBO.PAYROLL.EMPLOYEE_SEARCH":             "Employees can be filtered by location and employment status; the import template requires a Fully Qualified Location (e.g. 'All Offices / NSW Offices / Strathfield') for nested locations. If 'Automatically create missing locations' is not ticked on import, unmapped location names cause an import error. L9z7nKImX",
	"QBO.PAYROLL.EMPLOYEE_TERMINATE":          "Finalise every open pay run first. Inactive after terminate; record turns pink with leave payout. STP reason required. L3ek5ukSc.",
	"QBO.PAYROLL.LEAVE_BALANCE_EDIT":          "Correct accrual hours; does not rewrite lodged STP by itself. L9ksKvxAc.",
	"QBO.PAYROLL.LEAVE_CATEGORY_CREATE":       "Leave categories including LSL. L53E6mh31 L9AJEJFec.",
	"QBO.PAYROLL.LEAVE_CATEGORY_EDIT":         "Edit leave category / LSL settings. L9AJEJFec.",
	"QBO.PAYROLL.LEAVE_CATEGORY_READ":         "Read leave categories configured for the company.",
	"QBO.PAYROLL.LUMP_SUM_CREATE":             "Method A or B(ii) for PAYG/STSL on lump sums. Employment Hero can calculate; ask the accountant which method. L1GYkpZ9U.",
	"QBO.PAYROLL.OVERVIEW_SEARCH":             "The Single Touch Payroll page lists all historical Pay Events and Update Events for a financial year and can be filtered by event type. Pay events and update events lodged to the ATO cannot be deleted; correct YTD/super via a subsequent pay event or an ad hoc pay run. L5CSlXqAe",
	"QBO.PAYROLL.PAYG_SUMMARY_CREATE":         "STP-exempt employers only. After lodge, hover Status for the ATO receipt. L3FCpWWrh.",
	"QBO.PAYROLL.PAY_CATEGORY_CREATE":         "Pay Categories define the rates employees are paid; linked categories inherit settings (super, leave accrual) and add a penalty/loading on top of a parent category. A pay category with a 0% super rate, or a rate differing from the current financial year's applicable rate, will not be auto-updated by QuickBooks; audit before each FY. L3RTNw9Xc",
	"QBO.PAYROLL.PAY_CATEGORY_EDIT":           "STP Phase 2 requires paid leave taken to be reported under the correct leave classification; leave categories must be remapped if they were set up before Phase 2. Editing a pay category's STP classification affects future pay events only; past lodged events are not retroactively corrected (use an update event). L3RTNw9Xc",
	"QBO.PAYROLL.PAY_CATEGORY_READ":           "Pay categories expose rate, super-attracting, leave-accruing and STP classification attributes; bulk pay-rate updates can change up to 200 employees' rates at once. QuickBooks will not auto-update a pay category rate that is 0% or differs from the current FY applicable rate. L3RTNw9Xc",
	"QBO.PAYROLL.PAY_RUN_CREATE":              "A pay run is created from a pay schedule; there is no limit to the number of pay schedules and multiple weekly/fortnightly/monthly schedules can run concurrently. A finalised pay run cannot be unlocked or deleted if automated super payments have already been made from it. L1NVtqd21",
	"QBO.PAYROLL.PAY_RUN_INCLUSION_CREATE":    "Recurring inclusion on future pay runs for one employee. L9ZSdRoiL.",
	"QBO.PAYROLL.PAY_RUN_READ":                "The Pay Run Audit Report shows bank and super payments required for a pay run; it is only available on finalised pay runs. A pay run with automated super payments already made cannot be unlocked or deleted. L9cTlL8FB",
	"QBO.PAYROLL.SETUP_RUN":                   "AU payroll is QuickBooks Online Payroll powered by Employment Hero (formerly KeyPay); setup connects the QBO company to the payroll platform and configures STP compliance. STP must be enabled and ATO supplier settings configured before any pay event can be lodged to the ATO. L1EnJjXiU",
	"QBO.PAYROLL.STP_CLOSELY_HELD_LODGE":      "≤19 employees paying closely held staff must STP-report from 1 Jul 2021. Method: pay-day, quarterly, or estimate. L1oRPUfbZ.",
	"QBO.PAYROLL.STP_FINALISE":                "EOFY finalisation. Lodge the last FY pay run first. Prefer a dedicated finalisation event over a bare update. L4B7SA6SB.",
	"QBO.PAYROLL.STP_MICRO_LODGE":             "Micro-employer quarterly STP concession. L8loR7gso.",
	"QBO.PAYROLL.STP_PAY_CREATE":              "Lodge a pay event for a finalised pay run. Lodged events cannot be deleted. L5XLreOvf.",
	"QBO.PAYROLL.STP_RESET":                   "Reset incorrectly reported business/employee settings via an STP reset event. L5wfUkzSQ.",
	"QBO.PAYROLL.STP_UPDATE_CREATE":           "Lodge an update event (corrections / finalisation-via-update). L5kc65Mx6.",
	"QBO.PAYROLL.SUPER_PAY":                   "Super contributions are created when a pay run is finalised, based on pay schedule settings; track status via the super icon on the Pay Runs page. Under Payday Super contributions must reach the fund within 7 business days of payday; HeroClear is the recommended path to meet the deadline. L3UzoChSa",
	"QBO.PAYROLL.SUPER_READ":                  "Super payment status and historical batches can be viewed on the Pay Runs page and via the super contribution report. A pay category with a 0% or non-current super rate is not auto-updated; audit pay categories, pay rate templates and individual employee rates each FY. L3UzoChSa",
	"QBO.PAYROLL.SUPER_RESC_EDIT":             "Correct reportable employer super that STP is sending wrong. L4RwsRmGD.",
	"QBO.PAYROLL.TEAM_READ":                   "Payroll team members are firm users with permissions over payroll; restricted reporting access can be configured by manager, employee group and location. Restricted reporting does not grant pay-run processing rights; scope access by least privilege to protect sensitive employee payroll data. L13kRqbLq",
	"QBO.PAYROLL.TEAM_SEARCH":                 "Search returns firm team members and their payroll access level; filter by manager access, employee group or location for restricted reporting configurations. Full-access payroll managers can see all employee activities; restrict by group/location before exposing the team list to limited users. L13kRqbLq",
	"QBO.PAYROLL.TIMESHEET_CREATE":            "The timesheet feature must be enabled before creating or importing timesheets; CSV import is supported for single employees and third-party providers. Some timesheet details (e.g. specific work-type overrides) can only be entered via the timesheet editor (pencil icon), not the grid. L5td7UvqW",
	"QBO.PAYROLL.TIMESHEET_EDIT":              "The timesheet editor (pencil icon) exposes advanced fields not editable from the grid; changes apply via the Apply action. Editing a timesheet that has already flowed into a finalised pay run requires unlocking/recalculating the pay run, not just the timesheet. L5td7UvqW",
	"QBO.PAYROLL.TIMESHEET_READ":              "Timesheet costings can be viewed from the timesheet grid; the Actions menu provides additional features for reviewing submitted time. QBO (non-payroll) weekly timesheets support only a single hourly rate; multi-rate tracking requires QuickBooks Payroll. L5td7UvqW",
	"QBO.PAYROLL.WORKCOVER_CREATE":            "Workers compensation / WorkCover via a pay category. L6fnya3rA.",
	"QBO.REPORTS.CASH_FLOW_READ":              "Statement of Cash Flows shows cash in/out within a specific period and is accrual basis only. Cash Flow Planner is not available when Multicurrency is enabled, and is not available in QuickBooks Online Accountant. L7f72hT6Q",
	"QBO.REPORTS.CUSTOM_CREATE":               "Custom Report Builder / Report Builder requires QuickBooks Online Advanced. Using Report Builder counts against the monthly Intuit Intelligence chat prompt allowance. L4ORyzUla",
	"QBO.REPORTS.CUSTOM_READ":                 "View and manage saved custom/memorised reports from the Custom Reports list; Access column shows Private or Shared. Classic view: to change a custom report's permissions you must copy the report, change the setting, and delete the original. L2luznne3",
	"QBO.REPORTS.FORECAST_CREATE":             "Advanced forecasts — not the same as a budget. L7SlFsgsy.",
	"QBO.REPORTS.FORECAST_EDIT":               "Edit an Advanced forecast. L7SlFsgsy.",
	"QBO.REPORTS.FORECAST_READ":               "Read an Advanced forecast. L7SlFsgsy.",
	"QBO.REPORTS.MANAGEMENT_CREATE":           "Management reports are an Accountant bundle, not a standard P&L. L90RAh2XZ.",
	"QBO.REPORTS.MANAGEMENT_EDIT":             "Reorder management-report pages. L5sNxCAWt.",
	"QBO.REPORTS.MANAGEMENT_READ":             "View a management report. L90RAh2XZ.",
	"QBO.REPORTS.PERFORMANCE_CREATE":          "Performance centre holds all charts: Reports > Performance centre. Requires admin user (QuickBooks Online Advanced) or accountant user (QuickBooks Online) to create charts. L8m11b5qY",
	"QBO.REPORTS.PERFORMANCE_DELETE":          "Delete a chart from the Performance centre; built-in charts can also be deleted. Requires admin user (Advanced) or accountant user (QBO). L8m11b5qY",
	"QBO.REPORTS.PERFORMANCE_EDIT":            "Charts can be adjusted at any time from the Performance centre (metric, data, layout). Requires admin user (Advanced) or accountant user (QBO). L8m11b5qY",
	"QBO.REPORTS.PERFORMANCE_READ":            "The Performance centre dashboard shows all charts in one place (Reports > Performance centre). L8m11b5qY",
	"QBO.REPORTS.REPORT_CREATE":               "Save (memorise) a customised report to keep its filters/columns/settings; saved reports can be run, exported, printed, and grouped. Recurring email scheduling is not available in QuickBooks Online Simple Start. L8iRmBp9q",
	"QBO.REPORTS.REPORT_READ":                 "Reports are run from Reports > Standard reports; customise filters/columns then select Run report (Modern view) or Refresh report (Classic). PDF export has a 50,000-cell limit; export to Excel instead when a report exceeds it. L7aILHhbl",
	"QBO.SALES.CREDIT_CARD_CREDIT_CREATE":     "Credit card credits support custom fields (like other sales/expense forms). L7IjpiWLZ",
	"QBO.SALES.CREDIT_MEMO_CREATE":            "In AU, credit memos are called adjustment notes. Use one for an immediate credit; use a delayed credit for future use. Don't create an adjustment note for an item/service refund — that causes a double refund; use a refund receipt instead. L5kne9EiI",
	"QBO.SALES.CREDIT_MEMO_DELETE":            "Credit memos can be deleted but not voided (voiding is limited to invoices, payments and sales orders). Deletion is irreversible; the record remains only in the audit log. L5sZV8GYh",
	"QBO.SALES.CREDIT_MEMO_EDIT":              "If credits were auto-applied by mistake, you can remove them from the invoice. L5kne9EiI",
	"QBO.SALES.CREDIT_MEMO_READ":              "Adjustment notes can be downloaded/printed as PDFs. Customisations applied to the Standard template are picked up by the adjustment note. L6pyi04NN",
	"QBO.SALES.DELAYED_CHARGE_CREATE":         "A delayed charge records a charge now to be billed on a future invoice; it does not post until added to an invoice. L0T6cLpV0",
	"QBO.SALES.DELAYED_CREDIT_CREATE":         "A delayed credit is saved now and applied to a future invoice (unlike an adjustment note which is for immediate use). Adding a delayed credit to an invoice from a prior accounting period affects that period's balances. L5kne9EiI",
	"QBO.SALES.ESTIMATE_COPY":                 "Copy creates a new quote with the same lines; customer can change. Recurring is better for repeats. L1xisZLFD.",
	"QBO.SALES.ESTIMATE_CREATE":               "In AU, estimates are called quotes. A quote is a non-posting transaction — it does not affect your books until converted to an invoice. If a deposit is requested on a quote, it can only convert to an invoice after the customer pays the deposit and accepts the quote. L0kOXRjoP",
	"QBO.SALES.ESTIMATE_DELETE":               "You can delete a quote but cannot void it (voiding is limited to invoices, payments and sales orders). Deletion is irreversible; the record remains only in the audit log. L5sZV8GYh",
	"QBO.SALES.ESTIMATE_EDIT":                 "Editing a quote follows the same flow as editing an invoice. L4O0fokj0",
	"QBO.SALES.ESTIMATE_READ":                 "Quotes can be downloaded/printed as PDFs. A quote report shows customer, quote number, status and linked invoice number. L6pyi04NN",
	"QBO.SALES.ESTIMATE_SEARCH":               "Run a quotes report to see status of all proposals and which have been converted to invoices. L7hjsl70p",
	"QBO.SALES.HUB_READ":                      "Invoice = customer pays later (terms set how long). Sales receipt = customer pays on the spot. Bill = what you owe a supplier. Statement = summary of a customer's account activity. L6PMpw6hG",
	"QBO.SALES.HUB_SEARCH":                    "Filter the sales list to batch email/print or to locate marked forms. L7hjsl70p",
	"QBO.SALES.INVOICE_COPY":                  "Duplicates the invoice. Change customer if charging someone else. L93xhzbxn L1xisZLFD.",
	"QBO.SALES.INVOICE_CREATE":                "An invoice is used when the customer agrees to pay later; set terms to indicate how long they have to pay. If you forgot to add GST, correct the invoice before lodging your BAS — run a report to find invoices missing GST. L7gSzvCld",
	"QBO.SALES.INVOICE_CUSTOMISE":             "Customisation covers company info, logo, fields, appearance; preview via Print/Download. Custom field edits apply to all forms that use the field. L57kKA6b6",
	"QBO.SALES.INVOICE_DELETE":                "Voiding is recommended over deleting: it zeroes the amount and keeps a record in your books. Deleting a transaction is irreversible — it is removed everywhere except the audit log. L5sZV8GYh",
	"QBO.SALES.INVOICE_DISCOUNT":              "Turn discounts on in settings. Percent of subtotal or a negative-rate item. Turning off mid-invoice disables the setting company-wide. L3VyP6cwJ.",
	"QBO.SALES.INVOICE_EDIT":                  "Editing also applies to expenses, bills, estimates and other transactions via the same flow. Editing a paid invoice disconnects the linked payment and marks the invoice unpaid — reconnect the payment afterwards to avoid double-charging the customer. L4O0fokj0",
	"QBO.SALES.INVOICE_FORM_DELETE":           "Custom form styles are managed under Custom form styles; new styles appear in Other Templates. Deleting a form style does not delete transactions already created with it. L57kKA6b6",
	"QBO.SALES.INVOICE_LIST_CREATE":           "Add new products/services, customers and suppliers before importing. Imported customers without a set currency default to AUD; with multicurrency on you may import foreign-currency invoices. L7E9Xrd8l",
	"QBO.SALES.INVOICE_LIST_EDIT":             "Multiple invoices can be modified or deleted at once in Advanced. L46eRjDDv",
	"QBO.SALES.INVOICE_PROGRESS":              "Split a quote into partial invoices. Enable progress invoicing first. L0Ymm6WjR.",
	"QBO.SALES.INVOICE_READ":                  "Sales forms can be downloaded/printed as PDFs. L6pyi04NN",
	"QBO.SALES.INVOICE_REMIND":                "Automatic or one-off invoice reminders. L84cQjpxo.",
	"QBO.SALES.INVOICE_SEARCH":                "The sales list can be filtered to batch email/print or to find marked forms. L7hjsl70p",
	"QBO.SALES.INVOICE_SEND":                  "Email the invoice to the customer. L7bMJtO01.",
	"QBO.SALES.INVOICE_WRITE_OFF":             "Accountant write-off of an unpaid invoice to bad debt. L5tnLclDb.",
	"QBO.SALES.OVERVIEW_READ":                 "Use an invoice when the customer agrees to pay later; a sales receipt when they pay on the spot; a bill records what you owe a supplier; a statement summarises a customer's account. L6PMpw6hG",
	"QBO.SALES.PAYMENT_CREATE":                "Recording a payment tracks remaining balances and cash flow. With multicurrency, the Bank Deposit window shows one currency at a time — make a separate deposit per currency; all payments on a deposit must share a currency. L4ZadDW7F",
	"QBO.SALES.PAYMENT_DELETE":                "Payments can be voided (zeroes amount, keeps record) or deleted (removed except from audit log). Deletion is irreversible. Voiding is recommended over deleting for recordkeeping. L4ZadDW7F",
	"QBO.SALES.PAYMENT_EDIT":                  "On the mobile app, edit non-charge fields (date, reference number, memo); charge-affecting edits require the web. Editing/deleting a payment linked to other transactions triggers an automatic QuickBooks alert. L4QlrKfOS",
	"QBO.SALES.PAYMENT_READ":                  "Remaining balance for the customer is shown after recording a payment. L4ZadDW7F",
	"QBO.SALES.RECEIPT_CREATE":                "Use a sales receipt when the customer pays at the point of sale; without it the sale won't appear in income or reports. Match your deposit-to choice to how the bank records the deposit — grouping via Undeposited Funds keeps reconciliations accurate. L9vG2pbTQ",
	"QBO.SALES.RECEIPT_DELETE":                "Sales receipts can be deleted but not voided (voiding is limited to invoices, payments and sales orders). Deletion is irreversible; the record remains only in the audit log. L5sZV8GYh",
	"QBO.SALES.RECEIPT_EDIT":                  "On the mobile app you can edit non-charge fields (date, reference number, memo). For processed payments, charge-affecting edits must be done on the web. L7XDQhIeB",
	"QBO.SALES.RECEIPT_READ":                  "Sales receipts can be downloaded/printed as PDFs. L6pyi04NN",
	"QBO.SALES.REFUND_RECEIPT_CREATE":         "Use a refund receipt to refund a returned item or service; it updates sales, the chosen bank account, and item quantities. Don't enter an adjustment note for an item/service refund — that double-refunds the customer. L6aVbzEVi",
	"QBO.SALES.REFUND_RECEIPT_DELETE":         "Refund receipts can be deleted but not voided (voiding is limited to invoices, payments and sales orders). Deletion is irreversible; the record remains only in the audit log. L5sZV8GYh",
	"QBO.SALES.REFUND_RECEIPT_EDIT":           "Non-charge fields (date, reference number, memo) can be edited on the mobile app; charge-affecting edits require the web. L7XDQhIeB",
	"QBO.SALES.REFUND_RECEIPT_READ":           "Refund receipts can be downloaded/printed as PDFs. L6pyi04NN",
	"QBO.SALES.SALES_ORDER_CREATE":            "Sales orders are available only in QuickBooks Online Plus and Advanced. Saving a sales order updates committed quantities — verify stock levels before fulfilling. L1K2AQ1Lx",
	"QBO.SALES.SALES_ORDER_DELETE":            "Sales orders can be voided (in addition to deleted) — voiding zeroes the amount and keeps the record. Deletion is irreversible. L1K2AQ1Lx",
	"QBO.SALES.SALES_ORDER_EDIT":              "You can edit open sales orders that haven't been fulfilled, or whose linked invoice is voided/deleted. L1K2AQ1Lx",
	"QBO.SALES.SALES_ORDER_READ":              "Linked quote/invoices are visible in the Linked transactions section and via the link icon on line items. L1K2AQ1Lx",
	"QBO.SALES.SALES_ORDER_SEARCH":            "Sales orders can be filtered and managed from the sales orders list. L1K2AQ1Lx",
	"QBO.SALES.STATEMENT_CREATE":              "Statements remind customers of upcoming deadlines, unpaid balances or overdue invoices; they list transactions, finance charges and sub-customer activity. If a sub-customer is set to 'Bill parent customer', create the statement for the parent customer to include the sub-customer's transactions. L8bvb69Gg",
	"QBO.SALES.TIME_INVOICE_CREATE":           "Auto-invoice unbilled time on Essentials/Plus/Advanced. Then Sales → Invoices. L0M6412kT.",
	"QBO.TAX.ATO_CONNECT":                     "Connects QuickBooks Online to the ATO via the ATO Access Manager, reached from the GST centre; creates a secure channel for sharing BAS/IAS lodgements. ATO connectivity outages can block electronic BAS lodgement from within QuickBooks; check the Intuit status page during outages. L5YfVLVTR",
	"QBO.TAX.BAS_LODGE":                       "Lodgement flow: open the GST centre → Prepare BAS (or Prepare IAS) → confirm GST/PAYG amounts → Mark as lodged. 'Prepare' reviews figures; 'Mark as lodged' finalises the period with the ATO. Validation error 'One of the list elements assigned to this transaction has been deleted' when marking lodged: the PAYG Withholdings Payable account was deleted — reactivate it (saves as PAYG Withholdings Payable-1) and merge ...",
	"QBO.TAX.BAS_READ":                        "BAS Detail Report lists every transaction included in each BAS box; defaults to accrual basis unless GST reporting preference is set to cash. Adjust From/To dates to scope transactions. Reports opened from a menu/Reports page may default to today's date only — set explicit From/To dates covering the BAS period. L9212o1SU",
	"QBO.TAX.CODE_CREATE":                     "Custom tax rates and separate custom tax agencies are NOT supported — the system-generated ATO tax authority covers the majority of GST/BAS calculations for Australian small businesses. Disabling a tax rate only hides it from the GST dropdown on new transactions — existing transactions using that code are unaffected. L2Yt4K5G5",
	"QBO.TAX.CODE_DELETE":                     "There is no way to delete a GST rate in QuickBooks Online — deactivate it instead. Reactivate via the settings icon above the Action column → tick Include Inactive → switch the rate back to On. Deletion of a GST payment/refund blocked by closed books requires reopening (or unmatching) the period — coordinate before period close. L6JKrQWgQ",
	"QBO.TAX.CODE_EDIT":                       "Edit existing GST rates via GST centre → Settings → Edit rates (web only). Bulk reclassify changes historical transactions and can create GST exceptions/amendments in already-lodged BAS periods. L2Yt4K5G5",
	"QBO.TAX.CODE_READ":                       "Simpler GST codes (default for new files): GST, GST Free, Out of Scope. L4819AT7k",
	"QBO.TAX.CODE_SEARCH":                     "Transactions by Tax Code report gives a detailed breakdown of all transactions by GST code — use it to find wrongly coded transactions when BAS amounts look incorrect. Editing/saving a transaction in a filed period can create an exception even if the GST line item was not changed. L6NPaR5lf",
	"QBO.TAX.GST_AMENDMENTS_READ":             "The GST Amendments report shows amendments — changes carried forward when a transaction in a previously lodged BAS period is edited after lodgement — affecting the next BAS to be lodged. If impacted by the amendment issue and a BAS deadline is near, request a lodgement extension from the ATO directly (have the BAS and TFN ready). L7MEocluK",
	"QBO.TAX.GST_DEFERRED_CREATE":             "Record deferred GST liability. L9K8N1rLK.",
	"QBO.TAX.GST_PAYMENT_CREATE":              "Record the BAS/GST payment leaving the bank. Not the same as lodge. L8uFzN3iU.",
	"QBO.TAX.GST_PAYMENT_DELETE":              "Delete a recorded GST payment. L8GIJyLoa.",
	"QBO.TAX.GST_REFUND_CREATE":               "Record an ATO GST refund. L9ThKp2a1.",
	"QBO.TAX.GST_SETTINGS_EDIT":               "GST Settings (GST centre → Settings): GST on/off (irreversible once on), Lodging frequency (monthly/quarterly/annual; quarterly is the AU default), Accounting method (cash/accrual), and GST codes (Simpler vs Detailed). Once GST is turned on it cannot be turned off. Workarounds: reset the file if under 90 days old, or set the default tax rate to Out of Scope so new transactions post without GST. L2Yt4K5G5",
	"QBO.TAX.GST_SETUP":                       "Enabling GST in QuickBooks Online automatically applies GST to invoices, bills, and other transactions; line items take a GST code (GST 10%, GST-free, or Out of Scope) and QuickBooks calculates the GST amounts. Once GST is turned on by setting up BAS in the GST section, it cannot be turned off. L70qhnB9K",
	"QBO.TAX.IAS_READ":                        "An Instalment Activity Statement (IAS) is lodged monthly and is used when PAYG Withholding is reported monthly (with quarterly GST BAS), when PAYG Instalments are reported monthly, or when FBT is reported monthly. Reporting frequency choice determines IAS vs BAS: monthly PAYGW/PAYGI/FBT triggers IAS; quarterly triggers BAS. Confirm the ATO-mandated frequency before lodging. L5bqEalTv",
	"QBO.TAX.LODGEIT_EXPORT":                  "Import QBO BAS GST/PAYGW into LodgeiT, then pre-lodge. L2MFMlqt5 L4EUJdqX3.",
	"QBO.TAX.TPAR_EXPORT":                     "The Taxable Payments Annual Report (TPAR) is due 28 August every year and applies to businesses that pay contractors or subcontractors. If TPAR is not enabled in the account, the report will not appear even for eligible industries — enable it before the 28 August due date. L0SgQyxwc",
	"QBO.TAX.TPAR_READ":                       "TPAR tracks taxable payments made to contractors/subcontractors; the report is due 28 August annually. L5UqDoSGw",
}
